create or replace function public.settle_lottery_ticket_atomic(p_ticket_id uuid,p_matches integer,p_bonus_matched boolean,p_prize_cash integer,p_prize_xp integer,p_prize_fame integer) returns boolean language plpgsql security definer set search_path=public,pg_temp as $$ declare v_profile_id uuid; begin select profile_id into v_profile_id from public.lottery_tickets where id=p_ticket_id and claimed=false for update; if not found then return false; end if; update public.lottery_tickets set matches=p_matches,bonus_matched=p_bonus_matched,prize_cash=p_prize_cash,prize_xp=p_prize_xp,prize_fame=p_prize_fame,claimed=true where id=p_ticket_id; if p_prize_cash<>0 or p_prize_xp<>0 or p_prize_fame<>0 then update public.profiles set cash=coalesce(cash,0)+p_prize_cash,xp=coalesce(xp,0)+p_prize_xp,fame=coalesce(fame,0)+p_prize_fame where id=v_profile_id; if not found then raise exception 'Lottery profile not found'; end if; end if; return true; end $$;
revoke all on function public.settle_lottery_ticket_atomic(uuid,integer,boolean,integer,integer,integer) from public,anon,authenticated;
grant execute on function public.settle_lottery_ticket_atomic(uuid,integer,boolean,integer,integer,integer) to service_role;
